25	  stage_provider_calls: 40,         // per claimed stage
26	  iterations: 20,                   // stage attempts per tick
27	  stage_attempts: 3,                // retries of one stage of one item (failed attempts count)
28	  elapsed_ms: 60 * 60_000,
29	  concurrency: 1,
30	  lease_ms: 30 * 60_000,
31	  retry_after_ms: 15 * 60_000,
32	  recoveries: 50,                   // evidence-recovery searches per tick (no provider calls; reads and re-checks only)      // a TRANSIENT pending (a reviewer seat failed) is retried after this, within stage_attempts
33	});
