36	/** Provider calls already spent by the work ledger's stage records; unknown usage counts at its claim's budget. */
37	export function spent(work) {
38	  const claims = new Map(work.claims().map(c => [c.hash, c]));
39	  let calls = 0, unknown = 0;
40	  for (const s of work.stages()) {
41	    const c = s.usage?.provider_calls;
42	    if (Number.isInteger(c)) calls += c;
43	    else { const claim = claims.get(s.derived_from.find(h => claims.has(h))); calls += claim?.budget.provider_calls ?? 0; unknown++; }
44	  }
45	  return {calls, unknown_counted_at_budget: unknown};
46	}
