48	/** The receiving stage's check of its handoff: the record exists, is the same work, and is a valid start. */
49	export function verifyHandoff(work, gate) {
50	  if (!gate.from) {
51	    if (gate.gate !== 'plan') fail(`${gate.item}: ${gate.gate} has no handoff to start from`, 'HANDOFF');
52	    return null;
53	  }
54	  const rec = work.stages(gate.item).find(s => s.hash === gate.from);
55	  if (!rec) fail(`${gate.item}: the handoff ${String(gate.from).slice(0, 19)} is not a stage record of this item`, 'HANDOFF');
56	  const wanted = STAGES[STAGES.indexOf(gate.gate) - 1];
57	  if (rec.stage !== wanted) fail(`${gate.item}: ${gate.gate} receives from ${wanted}, not ${rec.stage}`, 'HANDOFF');
58	  if (rec.status !== 'passed') fail(`${gate.item}: the ${rec.stage} handoff is ${rec.status}, not passed`, 'HANDOFF');
59	  return rec;
60	}
