62	/** The signature of everything that can make new work ready or wake a waiting item. */
63	export function inputSignature({repo, statusRoot, workRoot, issues = null}) {
64	  const head = f => (fs.existsSync(f) ? fs.readFileSync(f, 'utf8').trim().split('\n').at(-1) ?? '' : '');
65	  const tdir = path.join(repo, 'tickets');
66	  const tickets = fs.existsSync(tdir) ? fs.readdirSync(tdir).filter(f => f.endsWith('.json')).sort().map(f => [f, fs.readFileSync(path.join(tdir, f), 'utf8')]) : [];
67	  return 'sha256:' + digest({status: head(path.join(statusRoot, 'chain.jsonl')), work: head(path.join(workRoot, 'chain.jsonl')), tickets,
68	    issues: (issues ?? []).map(i => [i.number, i.state, i.body ?? '']).sort((a, b) => a[0] - b[0])});
69	}
