65	/**
66	 * Where a unit's shim socket goes: <control_dir>/a2a.sock, or — when that is over SOCKET_PATH_MAX bytes — a short
67	 * path in a fresh controller-owned directory under os.tmpdir(). Returns {file, fallback, dir, wanted}.
68	 */
69	export async function a2aSocketFor(control_dir) {
70	  const wanted = join(control_dir, "a2a.sock");
71	  if (Buffer.byteLength(wanted) <= SOCKET_PATH_MAX) return { file: wanted, fallback: false, dir: control_dir, wanted };
72	  const short = await mkdtemp(join(tmpdir(), "pa2a-"));
73	  const file = join(short, "a2a.sock");
74	  if (Buffer.byteLength(file) > SOCKET_PATH_MAX) { await rm(short, { recursive: true, force: true }); throw Object.assign(new Error(`no Unix socket path fits ${SOCKET_PATH_MAX} bytes (os.tmpdir() is ${tmpdir()})`), { code: "SOCKET_PATH" }); }
75	  return { file, fallback: true, dir: short, wanted };
76	}
