198	    const issues = await fetchIssues();
199	    const sig = inputSignature({repo, statusRoot, workRoot, issues});
200	    // A tick runs when an input changed, or when a transient pending's retry is due (time is not an input).
201	    const now = (rest.clock ?? Date.now)();
202	    if (sig !== state.last || (state.due !== null && state.due !== undefined && now >= state.due)) {
203	      const t = await tick({repo, statusRoot, workRoot, issues, ...rest});
204	      ticks.push(t);
205	      state.last = inputSignature({repo, statusRoot, workRoot, issues});
206	      const dues = t.blocked.map(b => Date.parse(b.blocker?.retry_at ?? '')).filter(Number.isFinite);
