1	// UNIT CHECKPOINTS: an approved unit's result, kept across pipeline runs of the same item, so a re-run resumes
2	// instead of paying for work that was already approved.
3	//
4	// THE UNIT KEY (stable before dispatch, so it can be looked up before any provider is asked):
5	//   unit_key = "sha256:" + hex sha256 of canonical JSON (packages/ledger/canonical.mjs) of
6	//     {schema: "pantheon.unit-key/v1", unit: <the VALIDATED unit definition, every key of UNIT_KEYS, as planned>,
7	//      base_commit: <the run's resolved base commit>, upstream: [<unit_key of each TRANSITIVE upstream unit, in
8	//      unit_id order>]}
9	//   It holds the inputs of the frozen rubric hash (unit_id, owned_paths, verify_cmd, invariants) but not the
10	//   model-written rubric text, which only exists after dispatch. A changed unit, base or upstream definition
11	//   changes the key; nothing else does.
12	//
13	// THE FILE: <checkpoints.dir>/<hex of unit_key>.json, schema pantheon.unit-checkpoint/v1:
14	//   {schema, unit_key, unit_id, verdict: "approve", rubric_hash, base_commit (the run's base), unit_base_commit (the
15	//    unit's worktree base: base + upstream patches), upstream: [{unit_id, unit_key, tree}], commit, tree,
16	//    patch_path (relative to checkpoints.dir), patch_digest, reviewer: {vendor, model, served_model},
17	//    verify: {cmd, exit_code, digest}, recorded_at}
18	//   and the patch beside it at <hex>.patch. Both are written atomically (temp file + rename), patch first.
19	//
20	// A checkpoint is EVIDENCE TO RE-CHECK, never a verdict to trust: checkpointRefusal() refuses one whose schema,
21	// key, unit, base, verdict or upstream (unit set, keys and trees) differ from the current run, and whose patch bytes
22	// do not hash to patch_digest; the controller (index.mjs) then applies the patch on the unit's freshly bound base
23	// and refuses it unless the result is exactly the recorded tree.
24	//
25	// Must never: accept a checkpoint whose upstream trees differ from this run's; accept patch bytes that do not hash
26	// to the recorded digest; leave a half-written checkpoint where a reader would find it.
27	import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
28	import { join } from "node:path";
29	import { randomBytes } from "node:crypto";
30	import { digestOf, isObject, sha256, str } from "./util.mjs";
31	import { UNIT_KEYS } from "./work-units.mjs";
32	
33	export const CHECKPOINT_SCHEMA = "pantheon.unit-checkpoint/v1";
34	export const UNIT_KEY_SCHEMA = "pantheon.unit-key/v1";
35	const hexOf = key => String(key).replace(/^sha256:/, "");
36	
37	/** The unit key: see the header. `upstream_keys` are the transitive upstream units' keys (sorted here by unit_id). */
38	export function unitKey({ unit, base_commit, upstream = [] }) {
39	  const def = Object.fromEntries(UNIT_KEYS.map(k => [k, unit[k]]));
40	  const up = [...upstream].sort((a, b) => (a.unit_id < b.unit_id ? -1 : a.unit_id > b.unit_id ? 1 : 0)).map(u => ({ unit_id: u.unit_id, unit_key: u.unit_key }));
41	  return digestOf({ schema: UNIT_KEY_SCHEMA, unit: def, base_commit, upstream: up });
42	}
43	
44	export const checkpointFile = (dir, unit_key) => join(dir, `${hexOf(unit_key)}.json`);
45	export const patchFileName = unit_key => `${hexOf(unit_key)}.patch`;
46	
47	async function atomicWrite(file, data) {
48	  const tmp = `${file}.${randomBytes(4).toString("hex")}.tmp`;
49	  await writeFile(tmp, data);
50	  await rename(tmp, file);
51	}
52	
53	/** Write a checkpoint record and its patch. Returns the record as written. */
54	export async function writeCheckpoint({ dir, record, patch }) {
55	  await mkdir(dir, { recursive: true });
56	  const patch_path = patchFileName(record.unit_key);
57	  const full = { schema: CHECKPOINT_SCHEMA, ...record, verdict: "approve", patch_path, patch_digest: sha256(patch), recorded_at: record.recorded_at ?? new Date().toISOString() };
58	  await atomicWrite(join(dir, patch_path), patch);
59	  await atomicWrite(checkpointFile(dir, record.unit_key), JSON.stringify(full, null, 2) + "\n");
60	  return full;
61	}
62	
63	/** Read the checkpoint of `unit_key`: {found: false} | {found: true, record, patch, why?} (why: it could not be read). */
64	export async function readCheckpoint({ dir, unit_key }) {
