66	  try { text = await readFile(checkpointFile(dir, unit_key), "utf8"); } catch (e) { if (e?.code === "ENOENT") return { found: false }; return { found: true, record: null, patch: null, why: `the checkpoint could not be read: ${e.message}` }; }
67	  let record;
68	  try { record = JSON.parse(text); } catch { return { found: true, record: null, patch: null, why: "the checkpoint is not JSON" }; }
69	  if (!isObject(record) || !str(record.patch_path) || /[/\\]|^\.\.?$/.test(record.patch_path)) return { found: true, record, patch: null, why: "the checkpoint names no patch file beside it" };
70	  let patch;
71	  try { patch = await readFile(join(dir, record.patch_path), "utf8"); } catch (e) { return { found: true, record, patch: null, why: `the checkpoint's patch could not be read: ${e.code ?? e.message}` }; }
72	  return { found: true, record, patch };
