74	
75	/**
76	 * Why a read checkpoint may not be resumed, or null. `expect` is {unit_key, unit_id, base_commit, upstream:
77	 * [{unit_id, unit_key, tree}]} of the CURRENT run. The tree check (apply on the bound base) is the caller's.
78	 */
79	export function checkpointRefusal({ record, patch }, expect) {
80	  if (!isObject(record)) return "the checkpoint is not an object";
81	  if (record.schema !== CHECKPOINT_SCHEMA) return `the checkpoint's schema is ${record.schema}, not ${CHECKPOINT_SCHEMA}`;
82	  if (record.unit_key !== expect.unit_key) return "the checkpoint is for another unit key";
83	  if (record.unit_id !== expect.unit_id) return `the checkpoint is for unit ${record.unit_id}`;
84	  if (record.verdict !== "approve") return `the checkpoint's verdict is ${record.verdict}, not approve`;
85	  if (record.base_commit !== expect.base_commit) return `the checkpoint was recorded on base ${record.base_commit}, not ${expect.base_commit}`;
86	  if (!str(record.tree) || !/^[0-9a-f]{40,64}$/.test(record.tree)) return "the checkpoint records no tree";
87	  if (typeof patch !== "string") return "the checkpoint's patch is missing";
88	  if (sha256(patch) !== record.patch_digest) return `the checkpoint's patch hashes to ${sha256(patch)}, not the recorded ${record.patch_digest}`;
89	  const norm = list => (Array.isArray(list) ? list : []).map(u => `${u?.unit_id}\u0000${u?.unit_key}\u0000${u?.tree}`).sort();
90	  const got = norm(record.upstream), want = norm(expect.upstream);
91	  if (!Array.isArray(record.upstream) || got.length !== want.length || got.some((x, i) => x !== want[i])) return "the checkpoint's upstream units or their trees differ from this run's";
92	  return null;
93	}
