1	// THE WALK OVER A SEAT'S CANDIDATES, with the one rule the shared router does not know (owner direction 2026-11-17):
2	// a candidate marked `quota_failover` -- the metered Gemini API id of an Antigravity lane's base model -- is reached
3	// ONLY after one of the lanes it stands behind was refused for QUOTA: an attempt that packages/model-client
4	// classifyFailure classifies `quota` (HTTP 429 without an interval, or a quota-exhausted code), or that lane's quota
5	// authority already in a recorded quota cooldown. Any other lane failure (a transient error, a timeout, a wrong
6	// answer) never moves the turn to the metered API: the candidate is skipped and the walk continues past it.
7	//
8	// Everything else is routeCall's own behaviour, one candidate at a time: a non-retryable error is thrown as it is, a
9	// refused pool is not offered twice in one walk, and every refusal is written to the cooldown store.
10	//
11	// QUOTA AUTHORITY. A lane spends from the operator's Antigravity login, per base model; the API id spends from an API
12	// key. They are two authorities under one vendor name, so a lane's cooldown is keyed `agy_cli_oauth:<base model>` and
13	// never closes (or is closed by) the API pool. The recorded `pool` of a seat is unchanged.
14	import { routeCall, classifyFailure } from "../../../packages/model-client/index.mjs";
15	import { laneParts } from "./fit-matrix.mjs";
16	
17	export const cooldownKeyOf = c => (c.transport === "agy-cli" ? `agy_cli_oauth:${laneParts(c.model)?.base ?? c.model}` : c.pool);
18	
19	export async function routeSeats({ candidates, invoke, cooldown = null, signal, deadline, maxAttempts, onSkip = () => {} }) {
20	  if (!Array.isArray(candidates) || !candidates.length || typeof invoke !== "function") throw new Error("Routing needs candidates and invoke");
21	  const quota = new Map();      // lane model -> the quota refusal observed for it
22	  const closed = new Set(), attempts = [];
23	  for (const c of candidates) {
24	    const key = cooldownKeyOf(c);
25	    let seat = c;
26	    if (c.quota_failover) {
27	      const evidence = c.quota_failover.lanes.map(m => quota.get(m)).filter(Boolean);
28	      if (!evidence.length) {
29	        onSkip({ seat: c, why: `quota failover of ${c.quota_failover.lanes.join(", ")} not used: no quota refusal of that lane` });
30	        continue;
31	      }
32	      const used = { ...c.quota_failover, used: true, after: evidence };
33	      seat = { ...c, quota_failover: used, selection: c.selection ? { ...c.selection, quota_failover: { ...c.selection.quota_failover, ...used } } : c.selection };
34	    }
35	    if (closed.has(key)) continue;
36	    const view = cooldown ? { get: () => cooldown.get(key), refuse: (_p, row) => cooldown.refuse(key, row), success: () => cooldown.success(key) } : undefined;
37	    // A lane whose quota authority is already in a recorded QUOTA cooldown is quota evidence without a new call.
38	    if (c.transport === "agy-cli" && cooldown) {
39	      const held = await cooldown.get(key);
40	      if (held?.until > Date.now() && held.reason === "quota") quota.set(c.model, { lane: c.model, outcome: "quota", source: "cooldown", cooldown: key, until: held.until });
41	    }
42	    try {
43	      const routed = await routeCall({ candidates: [seat], cooldown: view, signal, ...(deadline === undefined ? {} : { deadline }), ...(maxAttempts === undefined ? {} : { maxAttempts }),
44	        invoke: async (s, ctx) => {
45	          try { return await invoke(s, ctx); }
46	          catch (e) {
47	            if (c.transport === "agy-cli" && classifyFailure(e).quota) quota.set(c.model, { lane: c.model, outcome: "quota", source: "attempt", status: e?.status ?? null, code: e?.code ?? null, why: String(e?.message ?? e).slice(0, 200) });
48	            throw e;
49	          }
50	        } });
51	      return { ...routed, attempts: [...attempts, ...routed.attempts], quota_failover: seat.quota_failover?.used ? seat.quota_failover : null };
52	    } catch (e) {
53	      if (e?.code !== "POOLS_UNAVAILABLE") throw e;
54	      attempts.push(...(e.attempts ?? []));
55	      closed.add(key);
56	    }
57	  }
58	  throw Object.assign(new Error("All configured credential pools unavailable"), { code: "POOLS_UNAVAILABLE", attempts });
59	}
