72	    const list = issueByItem.get(m[1]) ?? issueByItem.set(m[1], []).get(m[1]);
73	    list.push(issue.number);
74	    if (list.length === 2) duplicates.push({item: m[1], issues: list});
75	  }
76	  const bytesOf = bytesOfRepo(repo);
77	  const items = board.items.map(s => {
78	    const ticketFile = path.join(ticketsDir, `${s.item}.json`);
79	    const ticket = fs.existsSync(ticketFile) ? readTicket({repo, item: s.item}) : null;
80	    const stages = workLedger ? workLedger.stages(s.item) : [];
81	    const activeClaim = workLedger ? workLedger.activeClaim(s.item, now) : null;
82	    const gate = earliestGate({item: s, history: byItem.get(s.item) ?? [s], depStatus: d => latest.get(d) ?? null, ticket, stages, activeClaim, bytesOf, now,
83	      recovery: workLedger ? workLedger.recoveries(s.item).filter(r => r.status_entry === s.entry).at(-1) ?? null : null,
84	      reassessments: workLedger?.reassessments ? workLedger.reassessments(s.item) : [],
85	      // Only for a plan waiting on evidence: what the evidence looks like now (context.mjs), so a change wakes it.
86	      evidenceStable: stages.filter(x => x.stage === 'plan').at(-1)?.blocker?.code === 'EVIDENCE_INSUFFICIENT'
