60	  const spare = isLane ? quotaFailoverFor(model) : { vendor, model, effort: seat?.effort ?? null };
61	  try {
62	    const r = await lane({ vendor: viaLane.vendor, model: viaLane.model, prompt, seat });
63	    return { ...r, transport: "agy-cli", requested_model: model };
64	  } catch (e) {
