70	    const r = await api({ vendor: spare.vendor, model: spare.model, prompt, seat });
71	    return { ...r, transport: "api", requested_model: model,
72	      quota_failover: { used: true, base: spare.model, lanes: [viaLane.model], rule: QUOTA_FAILOVER_RULE,
73	        after: [{ lane: viaLane.model, outcome: "quota", source: "attempt", status: e?.status ?? null, code: e?.code ?? null, why: String(e?.message ?? e).slice(0, 200) }] } };
74	  }
