1	// ASYNC PROCESS EXECUTION for the pipeline controller: git, and the deterministic verify command.
2	//
3	// Inputs: a command, arguments, a working directory. Outputs: {code, stdout, stderr, timed_out, truncated}.
4	// Everything here is asynchronous `spawn`: the controller runs several units at once on one event loop, and one
5	// blocking child would stall every other unit's worker, shim and timer.
6	//
7	// Must never: block the event loop on a child process; run a repository's git hooks or signing as the controller;
8	// leave a timed-out command's process group running.
9	import { spawn } from "node:child_process";
10	
11	/** Run a child to completion. `max_bytes` caps EACH of stdout and stderr (the rest is dropped, `truncated: true`). */
12	export function exec(cmd, args, { cwd, input = null, env = process.env, timeout_ms = 0, max_bytes = 64 * 1024 * 1024, group = false } = {}) {
13	  return new Promise(resolve => {
14	    let child;
15	    try { child = spawn(cmd, args, { cwd, env, stdio: ["pipe", "pipe", "pipe"], detached: group }); }
16	    catch (e) { resolve({ code: null, signal: null, stdout: "", stderr: String(e.message), timed_out: false, truncated: false, spawn_error: true }); return; }
17	    const out = [], err = [];
18	    let nOut = 0, nErr = 0, truncated = false, timed_out = false, done = false;
19	    const take = (list, n, chunk) => {
20	      const room = max_bytes - n;
21	      if (room <= 0) { truncated = true; return 0; }
22	      if (chunk.length > room) { truncated = true; chunk = chunk.subarray(0, room); }
23	      list.push(chunk);
24	      return chunk.length;
25	    };
26	    child.stdout.on("data", c => { nOut += take(out, nOut, c); });
27	    child.stderr.on("data", c => { nErr += take(err, nErr, c); });
28	    child.stdin.on("error", () => {});
29	    const kill = () => { try { group ? process.kill(-child.pid, "SIGKILL") : child.kill("SIGKILL"); } catch { /* already gone */ } };
30	    const timer = timeout_ms > 0 ? setTimeout(() => { timed_out = true; kill(); }, timeout_ms) : null;
31	    const finish = (code, signal, spawn_error = false, msg = "") => {
32	      if (done) return;
33	      done = true;
34	      if (timer) clearTimeout(timer);
35	      resolve({ code, signal, stdout: Buffer.concat(out).toString("utf8"), stderr: Buffer.concat(err).toString("utf8") + msg, timed_out, truncated, spawn_error });
36	    };
37	    child.on("error", e => finish(null, null, true, String(e.message)));
38	    child.on("close", (code, signal) => finish(code, signal));
39	    child.stdin.end(input ?? "");
40	  });
41	}
