43	// The controller's own identity and a hook-free, unsigned, prompt-free git: what it commits must not depend on the
44	// repository's or the user's configuration.
45	const GIT_ENV = (() => {
46	  const env = { ...process.env, GIT_TERMINAL_PROMPT: "0", GIT_AUTHOR_NAME: "pantheon-controller", GIT_AUTHOR_EMAIL: "controller@pantheon.invalid", GIT_COMMITTER_NAME: "pantheon-controller", GIT_COMMITTER_EMAIL: "controller@pantheon.invalid" };
47	  for (const k of ["GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_PREFIX"]) delete env[k];
48	  return env;
49	})();
50	const GIT_FLAGS = ["-c", "commit.gpgsign=false", "-c", "core.hooksPath=/dev/null", "-c", "core.quotepath=false", "-c", "advice.detachedHead=false"];
51	
52	/** `git <args>` in `cwd`. Returns stdout; throws (code GIT_FAILED) on a non-zero exit unless `allowFail`, which returns the result object. */
53	export async function git(cwd, args, { input = null, allowFail = false } = {}) {
54	  const r = await exec("git", [...GIT_FLAGS, ...args], { cwd, input, env: GIT_ENV });
55	  if (allowFail) return r;
56	  if (r.code !== 0) throw Object.assign(new Error(`git ${args.join(" ")} exited ${r.code}: ${r.stderr.trim().slice(0, 2000)}`), { code: "GIT_FAILED", result: r });
57	  return r.stdout;
58	}
