60	/** A promise mutex: operations that touch the SHARED repository metadata (worktree add/remove) run one at a time. */
61	export function mutex() {
62	  let tail = Promise.resolve();
63	  return fn => { const run = tail.then(fn, fn); tail = run.then(() => {}, () => {}); return run; };
64	}
