178	export function escalate(state, event, cfg = {}) {
179	  const max = cfg.max_revisions ?? 3, after = cfg.reviewer_escalation_after ?? 2, iTop = (cfg.implementer_rungs ?? 1) - 1, rTop = (cfg.reviewer_rungs ?? 1) - 1;
