181	  if (state.revisions >= max) return { action: "blocked", state: { ...state }, escalations: [], why: `the unit's ${max} revision(s) are spent` };
182	  const next = { ...state, revisions: state.revisions + 1 }, escalations = [];
183	  if (event === "rejected") {
184	    if (next.implementer_level < iTop) { escalations.push({ kind: "implementer", from: next.implementer_level, to: next.implementer_level + 1 }); next.implementer_level += 1; }
185	    next.consecutive_rejections += 1;
186	    if (next.consecutive_rejections >= after && next.reviewer_level < rTop) {
187	      escalations.push({ kind: "reviewer", from: next.reviewer_level, to: next.reviewer_level + 1 });
188	      next.reviewer_level += 1; next.consecutive_rejections = 0;
189	    }
190	  }
