57	test("a tampered checkpoint is rejected with the reason and its unit re-runs: patch bytes changed, or the recorded tree changed", async t => {
58	  const env = await tempRepo(); t.after(env.cleanup);
59	  const checkpoints = { dir: join(env.root, "checkpoints") };
60	  const one = await go(env, "run1", good, checkpoints);
61	  assert.equal(one.out.status, "completed");
62	  // a: the patch bytes are changed (the digest no longer matches).
63	  const cpA = JSON.parse(readFileSync(one.out.units.a.checkpoint.file, "utf8"));
64	  const patchA = join(checkpoints.dir, cpA.patch_path);
65	  writeFileSync(patchA, readFileSync(patchA, "utf8").replace('"a"', '"evil"'));
66	  // b: the recorded tree is changed (its patch is left intact, so only the re-apply check can catch it).
67	  const fileB = one.out.units.b.checkpoint.file, cpB = JSON.parse(readFileSync(fileB, "utf8"));
68	  writeFileSync(fileB, JSON.stringify({ ...cpB, tree: "0".repeat(40) }));
69	  const two = await go(env, "run2", good, checkpoints);
70	  assert.equal(two.out.status, "completed");
71	  assert.match(two.out.units.a.checkpoint_rejected.why, /patch hashes to .* not the recorded/);
72	  assert.match(two.out.units.b.checkpoint_rejected.why, /yields tree [0-9a-f]+, not the recorded 0{40}/);
73	  for (const id of ["a", "b"]) { assert.equal(two.out.units[id].resumed, false); assert.equal(two.out.units[id].attempts.length, 1); }
74	  // c depends on a: a re-ran with identical content, so its tree is the same and c's checkpoint still holds.
75	  assert.equal(two.out.units.c.resumed, true);
76	  assert.deepEqual(two.out.checkpoints.rejected.sort(), ["a", "b"]);
77	  assert.deepEqual([...new Set(two.calls.map(c => c.unit_id))].sort(), ["a", "b"]);
78	  assert.doesNotMatch(await sh(`git show ${two.out.integration.branch}:src/a/impl.mjs`, env.repo), /evil/);
79	});
