1	// OWNED-PATH PATTERNS: the one grammar for a work unit's `owned_paths`, used by the plan validator, the lock check
2	// and the write jail.
3	//
4	// Grammar: a repo-relative path of `/`-separated segments. A segment is literal, or contains `*` (any run of
5	// characters inside one segment) or `?` (one character); the whole segment `**` matches zero or more segments.
6	// Nothing else is a wildcard: brackets, braces, `!` and backslashes are refused, so the matcher is exact.
7	//
8	// Inputs/outputs: strings in, booleans or refusal strings out. Pure; reads nothing.
9	//
10	// Must never: answer "disjoint" when unsure (pathsOverlap is conservative: a pattern that is a path prefix of the
11	// other overlaps it, because it may name a directory); let a pattern reach outside the repository or into `.git`.
12	
13	const GLOB = /[*?]/;
14	const reEscape = s => s.replace(/[.+^${}()|[\]\\]/g, "\\$&");
15	const segRe = seg => new RegExp("^" + seg.split("").map(c => c === "*" ? "[^/]*" : c === "?" ? "[^/]" : reEscape(c)).join("") + "$");
16	
17	/** Why `p` is not an owned-path pattern, or null. */
18	export function pathRefusal(p) {
19	  if (typeof p !== "string" || p.trim() === "") return "an owned path is a non-empty string";
20	  if (p !== p.trim()) return `"${p}" has leading or trailing space`;
21	  if (p.startsWith("/")) return `"${p}" has a leading "/": owned paths are repo-relative`;
22	  if (/^[A-Za-z]:/.test(p) || p.startsWith("~")) return `"${p}" is absolute: owned paths are repo-relative`;
23	  if (/[\\[\]{}!\0\n\r]/.test(p)) return `"${p}" uses a character outside the pattern grammar (only * ? and ** are wildcards)`;
24	  const segs = p.split("/");
25	  if (segs.includes("..")) return `"${p}" contains "..": an owned path may not leave the repository`;
26	  if (segs.some(s => s === "" || s === ".")) return `"${p}" has an empty or "." segment`;
27	  if (segs.some(s => s.includes("**") && s !== "**")) return `"${p}": "**" must be a whole segment`;
28	  if (segs[0].toLowerCase() === ".git") return `"${p}" is inside .git`;
29	  return null;
30	}
31	
32	function match(pat, segs) {
33	  if (!pat.length) return !segs.length;
34	  if (pat[0] === "**") return match(pat.slice(1), segs) || (segs.length > 0 && match(pat, segs.slice(1)));
35	  return segs.length > 0 && segRe(pat[0]).test(segs[0]) && match(pat.slice(1), segs.slice(1));
36	}
37	/** Does the concrete repo-relative `path` match one of `patterns`? Exact: a literal pattern owns that one path. */
38	export function matchesOwned(path, patterns) {
39	  const segs = String(path).split("/");
40	  if (segs.some(s => s === "" || s === "." || s === "..")) return false;
41	  return patterns.some(p => match(p.split("/"), segs));
42	}
43	
44	function segOverlap(a, b) {
45	  const ga = GLOB.test(a), gb = GLOB.test(b);
46	  if (!ga && !gb) return a === b;
47	  if (!ga) return segRe(b).test(a);
48	  if (!gb) return segRe(a).test(b);
49	  // Two wildcard segments: disjoint only when their literal heads or tails cannot both hold. Otherwise: overlap.
50	  const head = s => s.slice(0, s.search(GLOB)), tail = s => s.slice(Math.max(s.lastIndexOf("*"), s.lastIndexOf("?")) + 1);
51	  const ha = head(a), hb = head(b), ta = tail(a), tb = tail(b);
52	  return (ha.startsWith(hb) || hb.startsWith(ha)) && (ta.endsWith(tb) || tb.endsWith(ta));
53	}
54	function overlap(a, b) {
55	  if (!a.length || !b.length) return true;   // equal, or one is a path prefix of the other and may be a directory
56	  if (a[0] === "**") return overlap(a.slice(1), b) || overlap(a, b.slice(1));
57	  if (b[0] === "**") return overlap(a, b.slice(1)) || overlap(a.slice(1), b);
58	  return segOverlap(a[0], b[0]) && overlap(a.slice(1), b.slice(1));
59	}
60	/**
61	 * patternsOverlap without the grammar check on `b`: used against the RESERVED names (work-units.mjs), one of which
62	 * (`.git`) is itself refused as an owned path. `a` must be a valid pattern (else: true).
63	 */
64	export function overlapsReserved(a, reserved) {
65	  if (pathRefusal(a)) return true;
66	  return overlap(a.split("/"), reserved.split("/"));
67	}
68	/** Could two owned-path patterns name a common path (or one contain the other)? Conservative: unsure means true. */
69	export function pathsOverlap(a, b) {
70	  if (pathRefusal(a) || pathRefusal(b)) return true;
71	  return overlap(a.split("/"), b.split("/"));
72	}
